+// ArtistFolder returns the folder shared by the albums of an artist. Each
+// album normally has its own folder beneath the artist folder, so we use the
+// parent of its media directories. Albums whose media is spread across
+// multiple directories use their deepest common directory first.
+//
+// If the albums point to different artist folders, there is no safe local
+// image location to choose.
+func (als Albums) ArtistFolder() string {
+	var artistFolder string
+	for _, al := range als {
+		albumFolder := commonMediaDir(al.Dirs())
+		if albumFolder == "" {
+			continue
+		}
+
+		folder := filepath.Dir(albumFolder)
+		// Albums can also have their tracks directly in the artist folder.
+		// Prefer that directory when its name matches the album artist.
+		if al.AlbumArtist != "" && strings.EqualFold(filepath.Base(albumFolder), al.AlbumArtist) &&
+			!strings.EqualFold(filepath.Base(folder), al.AlbumArtist) {
+			folder = albumFolder
+		}
+		if folder == "." || folder == filepath.Dir(folder) {
+			return ""
+		}
+		if artistFolder != "" && artistFolder != folder {
+			return ""
+		}
+		artistFolder = folder
+	}
+	return artistFolder
+}
+
+// commonMediaDir finds the deepest directory that contains every media
+// directory. filepath.Rel keeps component boundaries intact (for example,
+// Artist and Artist Two do not share a directory named Artist).
+func commonMediaDir(dirs []string) string {
+	if len(dirs) == 0 {
+		return ""
+	}
+	base := filepath.Clean(dirs[0])
+	for _, dir := range dirs[1:] {
+		for {
+			rel, err := filepath.Rel(base, filepath.Clean(dir))
+			if err == nil && rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
+				break
+			}
+			parent := filepath.Dir(base)
+			if parent == base {
+				return ""
+			}
+			base = parent
+		}
+	}
+	return base
+}
